('banner-1-gosen-ryzonic', 'GOSEN RYZONIC 62 — CƯỚC CẦU LÔNG CAO CẤP', '/images/banners/banner-1-gosen-ryzonic.png', '/day-cuoc', 1, true, 'NEW MODEL — MADE IN JAPAN', 'Dòng cước cao cấp 0.62mm độ nảy tối đa, lực đập bộc phát, âm thanh nổ vang rền và đường cầu kiểm soát sắc nét.', 'Khám phá cước Gosen', 'Căng cước lấy ngay', '/day-cuoc', 'Gosen Ryzonic 62 String', 'Cước thi đấu BWF', '["Sức mạnh bộc phát 10/10", "Âm thanh nổ vang rền 9/10", "Độ nhám kiểm soát cầu 9.5/10"]'::jsonb),

('banner-2-dam-me-san-cau', 'ĐAM MÊ BẮT ĐẦU TỪ SÂN — VỢT, GIÀY, QUẦN ÁO, PHỤ KIỆN', '/images/banners/banner-2-dam-me-san-cau.png', '/vot-cau-long', 2, true, 'PLAY BETTER EVERYDAY', 'Trang bị thi đấu cầu lông chính hãng toàn diện: Vợt Yonex, giày bám sân cao cấp, bao vợt và phụ kiện chuyên nghiệp.', 'Mua ngay', 'Hệ thống cửa hàng', '/chi-nhanh', 'Hệ sinh thái Yonex chính hãng', 'Bộ sưu tập mới', '["Hàng chính hãng 100%", "Giao hàng nhanh toàn quốc", "Tư vấn tận tâm 24/7"]'::jsonb),

('banner-3-but-pha-san-cau', 'BỨT PHÁ TRÊN SÂN CẦU — BỘ SƯU TẬP THỂ THAO ĐỈNH CAO', '/images/banners/banner-3-but-pha-san-cau.png', '/vot-cau-long', 3, true, 'BỘ SƯU TẬP MỚI 2026', 'Trang phục thi đấu phối màu đỏ đen rực lửa, giày thi đấu trợ lực gót chân, balo chống sốc và vợt tấn công uy lực.', 'Khám phá ngay', 'Xem quần áo thi đấu', '/quan-ao', 'Bộ sưu tập Bứt Phá Sân Cầu', 'Sản phẩm mới', '["Áo đấu co giãn 4 chiều", "Giày đệm chống chấn", "Balo đựng vợt cách nhiệt"]'::jsonb),

('banner-4-rise-smash-repeat', 'RISE. SMASH. REPEAT. — BỨT PHÁ GIỚI HẠN CỦA BẠN', '/images/banners/banner-4-rise-smash-repeat.png', '/vot-cau-long', 4, true, 'BADMINTON PERFORMANCE', 'Vũ khí và trang thiết bị tốc độ cao tông xanh neon điện năng, tối đa hóa lực smash và tốc độ phản xạ liên hoàn trên sân.', 'Khám phá bộ sưu tập', 'Thử vợt tại quầy', '/chi-nhanh', 'Rise Smash Repeat Collection', 'Phiên bản thi đấu', '["Vợt đầu nhẹ trợ lực phản tạt", "Giày đế gai bám sân tuyệt đối", "Trang phục thấm hút mồ hôi siêu tốc"]'::jsonb);
